/** Add RUN-generated houses, house backs, fences/walls and POI dressing to the town builder library.
 *  node scripts/town-builder/register-generated.mjs
 *  Each sprite gets a footprint in game tiles (fw x fh, 1 tile = 2 m), is scaled so its drawn base spans that footprint in
 *  the 2:1 view, and its anchor is put on the footprint centre (bottom ground corner minus (fw+fh)*16 px). Shadows are
 *  then generated by shadows.mjs. Re-running replaces the same ids. */
import fs from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';
import {ROOT} from '../lib/town-scene.mjs';
import {ensureShadows} from './shadows.mjs';
const LIB=path.join(ROOT,'output/town-builder/library'),TM=path.join(ROOT,'output/terrain-materials');
const SPEC={ // id: [name, category, fw, fh]
 'house-ranch-long':['Ranch house — long, carport','Houses',7,3],'house-l-shape':['Colonial — L-shape, double garage','Houses',5,4],'house-splitlevel':['Split-level house','Houses',4,4],
 'house-l-ranch':['Ranch — L-shape, corner porch','Houses',5,4],'house-duplex':['Duplex','Houses',6,3],'house-farmhouse-wrap':['Farmhouse — wraparound porch','Houses',6,4],
 'back-bbq-deck':['House back — deck & barbecue','House backs',5,4],'back-patio-pool':['House back — patio & pool','House backs',5,4],'back-screened-porch':['House back — screened porch','House backs',4,4],
 'back-swingset':['House back — swing set & grill','House backs',5,4],'back-shed-garden':['House back — shed & garden','House backs',5,4],
 'fence-privacy-wood':['Privacy fence (8 m)','Fences & walls',4,.3],'fence-chainlink':['Chain-link fence (8 m)','Fences & walls',.3,4],'wall-brick-low':['Low brick wall (8 m)','Fences & walls',4,.4],
 'wall-stone-dry':['Fieldstone wall (8 m)','Fences & walls',4,.45],'fence-picket-gate':['Picket fence with gate (6 m)','Fences & walls',3,.3],'fence-split-rail':['Split-rail fence (8 m)','Fences & walls',4,.3],
 'wheelbarrow-leaves':['Wheelbarrow of leaves','POI dressing',.7,.45],'lawnmower':['Push lawn mower','POI dressing',.5,.35],'kids-bikes':["Kids' bikes",'POI dressing',.9,.6],'kiddie-pool':['Kiddie pool','POI dressing',.8,.8],
 'birdbath-gnome':['Birdbath & gnome','POI dressing',.6,.5],'inflatable-pumpkin':['Inflatable jack-o-lantern','POI dressing',.8,.8],'yard-tombstones':['Yard tombstones','POI dressing',.9,.5],'porch-rocker':['Porch rocker','POI dressing',.5,.5],
 'cooler-lawnchairs':['Cooler & lawn chairs','POI dressing',1,.7],'newspaper-box':['Newspaper boxes','POI dressing',.6,.35],'trash-cans-row':['Trash cans','POI dressing',.9,.45],'firewood-stack':['Firewood & chopping stump','POI dressing',.9,.5],
 'garden-hose-reel':['Hose reel & watering can','POI dressing',.5,.4],'basketball-hoop':['Driveway basketball hoop','POI dressing',.5,.5],'mailbox-post-fancy':['Spooky mailbox','POI dressing',.3,.3],'sandwich-board':['Sidewalk sale sign','POI dressing',.35,.25],
 'shopping-carts':['Abandoned shopping carts','POI dressing',.9,.6],'crates-pumpkins':['Crates of pumpkins','POI dressing',.8,.6]};
const lib=JSON.parse(await fs.readFile(path.join(LIB,'library.json'),'utf8'));let added=0;
for(const dir of ['new-buildings','poi-dressing'])for(const f of await fs.readdir(path.join(TM,dir)).catch(()=>[])){
 const key=path.basename(f,'.png'),spec=SPEC[key];if(!spec||!f.endsWith('.png'))continue;const [name,category,fw,fh]=spec,file=path.join(TM,dir,f);
 const {data,info}=await sharp(file).ensureAlpha().raw().toBuffer({resolveWithObject:true});
 for(let i=0;i<info.width*info.height;i++){const o=i*4;if(Math.min(data[o],data[o+1],data[o+2])>228&&data[o+3]<250)data[o+3]=0;} // white halo
 const t=await sharp(data,{raw:{width:info.width,height:info.height,channels:4}}).trim({threshold:1}).raw().toBuffer({resolveWithObject:true}),W=t.info.width,H=t.info.height,A=(x,y)=>t.data[(y*W+x)*4+3];
 // drawn base: lowest opaque point (the front ground corner) and the left/right extremes of the lower third
 let bx=0,by=-1;for(let y=H-1;y>=0&&by<0;y--)for(let x=0;x<W;x++)if(A(x,y)>120){bx=x;by=y;break;}
 let x0=W,x1=0;for(let y=Math.floor(H*.55);y<H;y++)for(let x=0;x<W;x++)if(A(x,y)>120){if(x<x0)x0=x;if(x>x1)x1=x;}
 const spanPx=Math.max(8,x1-x0),targetW=(fw+fh)*64,scale=targetW/spanPx,w=W*scale,h=H*scale;
 // footprint centre: from the front corner, back along both axes
 // footprint left/right corners sit at centre -/+ (fw+fh)*32, so the centre x is their midpoint; y from the lowest ground point
 const ax=(x0+x1)/2*scale,ay=by*scale-(fw+fh)*16;
 const id='gen:'+key,safe='gen_'+key.replace(/[^a-z0-9_-]/gi,'_');
 await sharp(t.data,{raw:{width:W,height:H,channels:4}}).resize(Math.round(w*2),Math.round(h*2),{kernel:'lanczos3'}).webp({quality:92,alphaQuality:100}).toFile(path.join(LIB,'sprites',safe+'.webp'));
 await sharp(t.data,{raw:{width:W,height:H,channels:4}}).resize(112,112,{fit:'contain',background:{r:0,g:0,b:0,alpha:0}}).webp({quality:85}).toFile(path.join(LIB,'thumbs',safe+'.webp'));
 const item={id,name,category,file:'sprites/'+safe+'.webp',thumb:'thumbs/'+safe+'.webp',w:+w.toFixed(1),h:+h.toFixed(1),ax:+ax.toFixed(1),ay:+ay.toFixed(1),fw,fh,flat:false,source:path.relative(ROOT,file).replace(/\\/g,'/'),tags:['generated','RUN']};
 const i=lib.items.findIndex(x=>x.id===id);if(i>=0)lib.items[i]=item;else lib.items.push(item);added++;}
lib.categories=[...new Set(lib.items.map(i=>i.category))];
const out=path.join(LIB,'library.json');await fs.writeFile(out+'.pending',JSON.stringify(lib,null,1));await fs.rename(out+'.pending',out);
console.log('registered',added);await import('./calibrate-fences.mjs');await ensureShadows();
